def is_samepatterns(colors, patterns):
    # Check if the lengths of the two lists are the same
    if len(colors) != len(patterns):
        return False

    # Create dictionaries to map colors to patterns and patterns to colors
    color_to_pattern = {}
    pattern_to_color = {}

    # Iterate through the lists to populate the dictionaries
    for color, pattern in zip(colors, patterns):
        if color in color_to_pattern and color_to_pattern[color] != pattern:
            return False
        if pattern in pattern_to_color and pattern_to_color[pattern] != color:
            return False
        color_to_pattern[color] = pattern
        pattern_to_color[pattern] = color

    # If all mappings are consistent, return True
    return True
```

